function findWayScene(){
 const strip=['THE NEED','THE CONSTRAINT','THE WAY','DELIVERED'].map((t,i)=>`<g class="seq4" style="--n:${i}" transform="translate(${40+i*232} 150)"><rect class="fw-chip" width="216" height="36" rx="3"/>${text(108,23,t,'center mini-label')}</g>`).join('');
 const traveller=(d,dur=5)=>`<circle class="fw-dot" r="8"><animateMotion path="${d}" dur="${dur}s" repeatCount="indefinite"/></circle>`;
 const node=(id,x,y,t,sub,body,cls='')=>hint(id,t,body,`<g transform="translate(${x} ${y})"><rect class="fw-node ${cls}" x="-95" y="-30" width="190" height="60" rx="4"/>${text(0,-4,t,'center mini-label')}${text(0,16,sub,'center label tiny')}</g>`);
 const wall=(id,x,y,h,t,body)=>hint(id,t,body,`<g><rect class="fw-wall" x="${x-12}" y="${y}" width="24" height="${h}" rx="3"/>${text(x,y-12,t,'center mini-label warm')}</g>`);
 const vfli=`<g class="state-layer" data-states="0">
  ${node('fw-need0',140,430,'A TRAIN TO RUN','Tonight, as promised','A customer’s freight train, due at a given place and hour.')}
  ${wall('fw-wall0',500,330,200,'NO LOCOMOTIVE · NO DRIVER','The resource the train needed was missing, at the last minute.')}
  ${node('fw-way0',500,260,'ANOTHER COMPANY','Convinced to make one available','I convinced another company to make a shunting locomotive or a driver available.','is-way')}
  ${node('fw-done0',860,430,'THE TRAIN RUNS','Agreement obtained','With the last-minute circulation agreement obtained, the train ran.','is-done')}
  ${line('M235 430H488','fw-path blocked')}${line('M235 430C330 430 360 260 405 260M595 260C640 260 670 430 765 430','fw-path')}
  ${traveller('M235 430C330 430 360 260 500 260C640 260 670 430 765 430')}</g>`;
 const years=['Y−3','Y−2','Y−1','D'];
 const rff=`<g class="state-layer" data-states="1">
  ${line('M120 640H900','fw-axis')}${years.map((y,i)=>text(120+i*260,664,y,'center mini-label'))}
  ${node('fw-need1',140,300,'A CAPACITY REQUEST','For a freight customer','The train paths a customer needs, requested two or three years ahead.')}
  ${[[300,380,'WORKS'],[560,250,'COMPETING DEMAND'],[720,420,'WORKS']].map(([x,y,t],i)=>wall(`fw-wall1-${i}`,x,y,120,t,i===1?'Other operators want the same capacity.':'Engineering works take capacity away for a period.')).join('')}
  ${node('fw-done1',860,560,'THE TRAIN RUNS','On the day','I kept the request alive until the train ran.','is-done')}
  ${line('M235 300C270 300 270 540 330 540S420 300 470 300 520 540 600 540 680 330 760 330 820 560 765 560','fw-path')}
  ${traveller('M235 300C270 300 270 540 330 540S420 300 470 300 520 540 600 540 680 330 760 330 820 560 765 560',7)}</g>`;
 const tour=`<g class="state-layer" data-states="2">
  ${line('M80 420H920','race-road')}${line('M80 420H920','race-line')}${line('M500 230V640','track-bed')}${line('M500 230V640','track-ties')}
  ${wall('fw-wall2',500,380,80,'THE RACE AT THE CROSSING','The race and the train need the same point.')}
  ${node('fw-need2',220,300,'STAGE ROUTE + TIMING','From the race organiser','The race organiser’s schedule for each stage.')}
  ${node('fw-way2',780,300,'EACH REGION CONCERNED','Train held, then released','I turned the stage timing into crossing-by-crossing needs for each region.','is-way')}
  ${node('fw-done2',780,560,'FIVE YEARS','Every stage','Five years of Tour de France stages coordinated this way.','is-done')}
  <g class="fw-train"><rect x="-8" y="-20" width="16" height="40" rx="3"/><animateMotion path="M500 240V640" calcMode="linear" keyPoints="0;.3;.3;1" keyTimes="0;.3;.7;1" dur="6s" repeatCount="indefinite"/></g>
  <g class="fw-race">${[0,1,2,3].map(i=>`<circle cx="${-i*14}" r="5"/>`).join('')}<animateMotion path="M80 420H920" calcMode="linear" keyPoints="0;0;1" keyTimes="0;.3;.7" dur="6s" repeatCount="indefinite"/></g></g>`;
 const food=`<g class="state-layer" data-states="3">
  ${hint('fw-need3','600+ dashboards','Everything on Tableau, with the licence ending in six weeks.',`<g>${Array.from({length:120},(_,i)=>`<rect class="fw-tile" x="${80+(i%12)*20}" y="${250+Math.floor(i/12)*20}" width="14" height="14" rx="2"/>`).join('')}${text(80,236,'600+ DASHBOARDS','mini-label')}</g>`)}
  ${hint('fw-wall3','Six weeks','The licence ended in six weeks: everything could not move in time.',`<g transform="translate(420 260)"><path class="fw-funnel" d="M0 0H160L100 120V200H60V120Z"/>${text(80,-12,'SIX WEEKS','center mini-label warm')}</g>`)}
  ${[0,1,2,3,4,5].map(k=>`<rect class="fw-bit ${k%3===0?'is-kept':''}" width="12" height="12" rx="2"><animateMotion path="${k%3===0?'M330 300L500 300L500 470L700 470':'M330 300L470 300L470 320'}" dur="3s" begin="-${(k*.5).toFixed(1)}s" repeatCount="indefinite"/></rect>`).join('')}
  ${node('fw-done3',800,470,'THE CRITICAL VIEWS','Live on day one','The board and finance views ran in Metabase before the licence ended.','is-done')}
  ${caseChip(600,560,320,'food-deadline','HIGH-STAKES · SIX WEEKS','The full case')}</g>`;
 return `${ops.opsDefs}${ops.header('FIND A WAY · WHATEVER THE CONSTRAINT')}${strip}${vfli}${rff}${tour}${food}`;
}
